CREATE TABLE write_lock(id INTEGER PRIMARY KEY, value INTEGER NOT NULL);
INSERT INTO write_lock VALUES(1,0);
CREATE TABLE books(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL CHECK(length(trim(title))>0),author TEXT NOT NULL, isbn TEXT UNIQUE,category TEXT NOT NULL,description TEXT,publisher TEXT,publication_year INTEGER,shelf_location TEXT,total_copies INTEGER NOT NULL CHECK(total_copies>=0),active BOOLEAN NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE borrowers(id INTEGER PRIMARY KEY AUTOINCREMENT,full_name TEXT NOT NULL,phone_number TEXT NOT NULL,whatsapp_number TEXT,email TEXT,address TEXT,membership_date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('ACTIVE','DISABLED')),notes TEXT,whatsapp_consent BOOLEAN NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE loans(id INTEGER PRIMARY KEY AUTOINCREMENT,book_id INTEGER NOT NULL REFERENCES books(id),borrower_id INTEGER NOT NULL REFERENCES borrowers(id),loan_date TEXT NOT NULL,due_date TEXT NOT NULL,returned_at TEXT,status TEXT NOT NULL CHECK(status IN ('ACTIVE','RETURNED')),renewal_count INTEGER NOT NULL DEFAULT 0 CHECK(renewal_count>=0),notes TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK(due_date>=loan_date),CHECK((status='ACTIVE' AND returned_at IS NULL) OR (status='RETURNED' AND returned_at IS NOT NULL)));
CREATE INDEX idx_loans_active ON loans(status,due_date);
CREATE INDEX idx_loans_book ON loans(book_id,status);
CREATE INDEX idx_loans_borrower ON loans(borrower_id,status);
CREATE TABLE renewals(id INTEGER PRIMARY KEY AUTOINCREMENT,loan_id INTEGER NOT NULL REFERENCES loans(id),old_due_date TEXT NOT NULL,new_due_date TEXT NOT NULL,renewed_at TEXT NOT NULL);
CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,full_name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('ADMIN','LIBRARIAN')),enabled BOOLEAN NOT NULL,created_at TEXT NOT NULL,last_login_at TEXT);
CREATE TABLE reminder_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,loan_id INTEGER NOT NULL REFERENCES loans(id),reminder_type TEXT NOT NULL,prepared_at TEXT NOT NULL,whatsapp_opened_at TEXT,manually_confirmed_sent_at TEXT,status TEXT NOT NULL,message TEXT NOT NULL);
CREATE INDEX idx_reminder_loan ON reminder_logs(loan_id,prepared_at);
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1),library_name TEXT NOT NULL,default_days INTEGER NOT NULL CHECK(default_days BETWEEN 1 AND 365),max_renewals INTEGER NOT NULL CHECK(max_renewals BETWEEN 0 AND 20),lead_days INTEGER NOT NULL CHECK(lead_days BETWEEN 1 AND 30),backup_keep INTEGER NOT NULL CHECK(backup_keep BETWEEN 1 AND 365),backup_directory TEXT NOT NULL,international_phones BOOLEAN NOT NULL,logo_path TEXT,due_template TEXT NOT NULL,overdue_template TEXT NOT NULL);
INSERT INTO settings VALUES(1,'مكتبة البركة',14,2,1,14,'backups',0,NULL,'السلام عليكم ورحمة الله وبركاته،\nالأخ/الأخت {borrowerName}،\nنذكركم بأن موعد إرجاع كتاب «{bookTitle}» هو {dueLabel} الموافق {dueDate}.\nنرجو منكم إرجاع الكتاب في الموعد المحدد.\nجزاكم الله خيرًا.\n{libraryName}','السلام عليكم ورحمة الله وبركاته،\nالأخ/الأخت {borrowerName}،\nنود تذكيركم بأن موعد إرجاع كتاب «{bookTitle}» كان بتاريخ {dueDate}، وقد تجاوز الموعد المحدد.\nنرجو منكم إرجاع الكتاب في أقرب وقت ممكن.\nشكرًا لتعاونكم.\n{libraryName}');
CREATE TRIGGER capacity_insert BEFORE INSERT ON loans WHEN NEW.status='ACTIVE' BEGIN SELECT CASE WHEN (SELECT COUNT(*) FROM loans WHERE book_id=NEW.book_id AND status='ACTIVE') >= (SELECT total_copies FROM books WHERE id=NEW.book_id) THEN RAISE(ABORT,'No available copies') END; END;
CREATE TRIGGER capacity_update BEFORE UPDATE OF total_copies ON books BEGIN SELECT CASE WHEN NEW.total_copies < (SELECT COUNT(*) FROM loans WHERE book_id=NEW.id AND status='ACTIVE') THEN RAISE(ABORT,'Copies below active loans') END; END;
